/**
 * Genera una esfera de voxels centrada en X/Z y apoyada sobre originY.
 * 
 * @param {number} originX - Coordenada X del centro de la base.
 * @param {number} originY - Coordenada Y de la base inferior.
 * @param {number} originZ - Coordenada Z del centro de la base.
 * @param {Object} [options] - Parámetros de configuración.
 * @param {number} [options.radius=10] - Radio de la esfera en voxels.
 * @param {boolean} [options.hollow=false] - Si es true, la esfera se genera hueca por dentro.
 * @param {number} [options.wallThickness=1] - Grosor de la cascara exterior si hollow es true.
 * @param {string|number} [options.material='stone'] - Material/bloque a utilizar.
 */
function buildGiantSphere(originX, originY, originZ, options = {}) {
    const radius = options.radius || 10;
    const hollow = options.hollow !== undefined ? options.hollow : false;
    const wallThickness = options.wallThickness || 1;
    const material = options.material || 'stone';

    if (typeof beginBatch === 'function') beginBatch();

    const startTime = performance.now();
    let blocksCreated = 0;

    const outerRadiusSq = radius * radius;
    const innerRadius = Math.max(0, radius - wallThickness);
    const innerRadiusSq = innerRadius * innerRadius;

    // Bounding box que envuelve a la esfera
    const minExtent = -radius;
    const maxExtent = radius;

    for (let dx = minExtent; dx <= maxExtent; dx++) {
        for (let dy = minExtent; dy <= maxExtent; dy++) {
            for (let dz = minExtent; dz <= maxExtent; dz++) {

                // Cálculo de la distancia al cuadrado desde el centro de la esfera (0,0,0 local)
                // Se usa +0.5 para muestrear desde el centro físico del voxel y evitar asimetrías
                const distSq = (dx + 0.5) * (dx + 0.5) + 
                               (dy + 0.5) * (dy + 0.5) + 
                               (dz + 0.5) * (dz + 0.5);

                // Si está fuera del radio exterior de la esfera, saltar
                if (distSq > outerRadiusSq) {
                    continue;
                }

                // Si es hueca y está por debajo del radio interior (corteza), saltar
                if (hollow && distSq < innerRadiusSq) {
                    continue;
                }

                // Mapeo a las coordenadas globales del mundo
                // (Centrado en X/Z, el punto inferior Y=0 toca originY)
                const targetX = originX + dx;
                const targetY = originY + dy + radius;
                const targetZ = originZ + dz;

                setVoxel(targetX, targetY, targetZ, material);
                blocksCreated++;
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();

    const endTime = performance.now();
    console.log(`🔮 Esfera generada (Radio: ${radius}, Diámetro: ${radius * 2}), en [${originX}, ${originY}, ${originZ}] Total voxels: ${blocksCreated}. Tiempo: ${(endTime - startTime).toFixed(2)}ms`);
}

var scale=20

